RIPE_DELEGATIONS_URL = "https://ftp.ripe.net/pub/stats/ripencc/delegated-ripencc-latest"


def add_default_sources(apps, schema_editor):
    """A group split before the lists existed gets the default source, as a new one does."""
    group_model = apps.get_model("groups", "ServerGroup")
    source_model = apps.get_model("relays", "SplitSource")
    for group in group_model.objects.filter(routing="split"):
        source_model.objects.create(group=group, url=RIPE_DELEGATIONS_URL, kind="ripe")


